
// App #1 - Atlas TaskFlow - Live Calendar
// Reads task data rendered by Razor from SQL Server.

document.addEventListener("DOMContentLoaded", function () {

    const calendarGrid =
        document.getElementById("calendarGrid");

    if (!calendarGrid) {
        return;
    }

    // 1. Read tasks from the HTML generated by Razor.
    const tasks = Array.from(
        document.querySelectorAll("[data-calendar-task]")
    ).map(function (element) {

        return {
            id: element.dataset.id,
            title: element.textContent.trim(),
            date: element.dataset.date,
            project: element.dataset.project,
            priority: element.dataset.priority,
            status: element.dataset.status,
            editUrl: element.dataset.editUrl
        };

    }).filter(task => task.date);

    // 2. Calendar state.
    const today = new Date();

    let displayedMonth = new Date(
        today.getFullYear(),
        today.getMonth(),
        1
    );

    let selectedDate = dateKey(today);
    let activeView = "month";

    const projectFilter =
        document.getElementById("calendarProjectFilter");

    const statusFilter =
        document.getElementById("calendarStatusFilter");

    // Convert a Date to yyyy-MM-dd.
    function dateKey(date) {

        const year = date.getFullYear();

        const month = String(
            date.getMonth() + 1
        ).padStart(2, "0");

        const day = String(
            date.getDate()
        ).padStart(2, "0");

        return year + "-" + month + "-" + day;
    }

    // Convert yyyy-MM-dd to a local Date object.
    function parseDate(key) {

        const parts = key.split("-").map(Number);

        return new Date(
            parts[0],
            parts[1] - 1,
            parts[2]
        );
    }

    // Format a date for display.
    function formatDate(key) {

        return parseDate(key).toLocaleDateString(
            "en-US",
            {
                month: "short",
                day: "numeric",
                year: "numeric"
            }
        );
    }

    // 3. Apply filters to real tasks.
    function getFilteredTasks() {

        return tasks.filter(function (task) {

            const matchesProject =
                !projectFilter.value ||
                task.project === projectFilter.value;

            const matchesStatus =
                !statusFilter.value ||
                task.status === statusFilter.value;

            return matchesProject && matchesStatus;

        }).sort(function (a, b) {

            return a.date.localeCompare(b.date);

        });
    }

    // 4. Create one task row.
    function createTaskRow(task) {

        const row = document.createElement("div");
        row.className = "wf-event-row";

        const dot = document.createElement("span");

        dot.className = "wf-dot " +
            (task.priority === "High" ||
             task.priority === "Urgent"
                ? "red"
                : task.priority === "Medium"
                    ? "orange"
                    : "green");

        const details = document.createElement("div");
        details.style.flex = "1";

        const title = document.createElement("strong");
        title.textContent = task.title;

        const description = document.createElement("p");
        description.textContent =
            task.project + " | " +
            formatDate(task.date) + " | " +
            task.status;

        description.style.fontSize = "11px";
        description.style.color = "#8190a7";

        const edit = document.createElement("a");

        edit.href = task.editUrl;
        edit.textContent = "Edit";

        edit.style.color = "#2563eb";
        edit.style.fontSize = "12px";

        details.appendChild(title);
        details.appendChild(description);

        row.appendChild(dot);
        row.appendChild(details);
        row.appendChild(edit);

        return row;
    }

    // 5. Show an empty message.
    function showEmpty(container, message) {

        const text = document.createElement("p");

        text.className = "wf-empty";
        text.textContent = message;

        container.appendChild(text);
    }

    // 6. Draw the month calendar.
    function renderMonth() {

        calendarGrid.replaceChildren();

        const year = displayedMonth.getFullYear();
        const month = displayedMonth.getMonth();

        const firstWeekday =
            new Date(year, month, 1).getDay();

        const daysInMonth =
            new Date(year, month + 1, 0).getDate();

        const numberOfCells = Math.ceil(
            (firstWeekday + daysInMonth) / 7
        ) * 7;

        const filtered = getFilteredTasks();

        const monthLabel =
            document.getElementById("calendarMonthLabel");

        monthLabel.textContent =
            displayedMonth.toLocaleDateString(
                "en-US",
                { month: "long", year: "numeric" }
            );

        for (let i = 0; i < numberOfCells; i++) {

            const date = new Date(
                year,
                month,
                i - firstWeekday + 1
            );

            const key = dateKey(date);

            const cell = document.createElement("button");

            cell.type = "button";
            cell.className = "wf-calendar-day";

            if (date.getMonth() !== month) {
                cell.classList.add("outside");
            }

            if (key === dateKey(today)) {
                cell.classList.add("today");
            }

            if (key === selectedDate) {
                cell.classList.add("selected");
            }

            const dayNumber =
                document.createElement("span");

            dayNumber.className = "wf-calendar-number";
            dayNumber.textContent = date.getDate();

            cell.appendChild(dayNumber);

            const dayTasks = filtered.filter(
                task => task.date === key
            );

            dayTasks.slice(0, 2).forEach(function (task) {

                const event = document.createElement("span");

                event.className = "wf-calendar-event";

                if (task.status === "Completed") {
                    event.classList.add("team");
                }

                event.textContent = task.title;

                cell.appendChild(event);

            });

            if (dayTasks.length > 2) {

                const more = document.createElement("small");

                more.textContent =
                    "+" + (dayTasks.length - 2) + " more";

                cell.appendChild(more);
            }

            cell.addEventListener("click", function () {

                selectedDate = key;

                displayedMonth = new Date(
                    date.getFullYear(),
                    date.getMonth(),
                    1
                );

                activeView = "day";

                renderAll();
            });

            calendarGrid.appendChild(cell);
        }
    }

    // 7. Draw tasks for the selected day.
    function renderDay() {

        const container =
            document.getElementById("calendarDayContent");

        const label =
            document.getElementById("calendarDayLabel");

        container.replaceChildren();

        label.textContent = formatDate(selectedDate);

        const dayTasks = getFilteredTasks().filter(
            task => task.date === selectedDate
        );

        if (dayTasks.length === 0) {

            showEmpty(
                container,
                "No scheduled tasks for this day."
            );

            return;
        }

        dayTasks.forEach(function (task) {

            container.appendChild(
                createTaskRow(task)
            );

        });
    }

    // 8. Draw the selected week.
    function renderWeek() {

        const container =
            document.getElementById("calendarWeekContent");

        const label =
            document.getElementById("calendarWeekLabel");

        container.replaceChildren();

        const selected = parseDate(selectedDate);

        const sunday = new Date(
            selected.getFullYear(),
            selected.getMonth(),
            selected.getDate() - selected.getDay()
        );

        label.textContent =
            "Week of " + formatDate(dateKey(sunday));

        const filtered = getFilteredTasks();

        for (let i = 0; i < 7; i++) {

            const date = new Date(
                sunday.getFullYear(),
                sunday.getMonth(),
                sunday.getDate() + i
            );

            const key = dateKey(date);

            const dayHeading =
                document.createElement("h4");

            dayHeading.textContent = formatDate(key);

            container.appendChild(dayHeading);

            const dayTasks = filtered.filter(
                task => task.date === key
            );

            if (dayTasks.length === 0) {

                showEmpty(container, "No tasks");

            } else {

                dayTasks.forEach(function (task) {

                    container.appendChild(
                        createTaskRow(task)
                    );

                });
            }
        }
    }

    // 9. Draw a chronological task list.
    function renderList() {

        const container =
            document.getElementById("calendarListContent");

        container.replaceChildren();

        const filtered = getFilteredTasks();

        if (filtered.length === 0) {

            showEmpty(container, "No scheduled tasks.");

            return;
        }

        filtered.forEach(function (task) {

            container.appendChild(
                createTaskRow(task)
            );

        });
    }

    // 10. Draw upcoming tasks.
    function renderUpcoming() {

        const container =
            document.getElementById("calendarUpcoming");

        container.replaceChildren();

        const todayKey = dateKey(new Date());

        const upcoming = getFilteredTasks()
            .filter(function (task) {

                return task.date >= todayKey &&
                    task.status !== "Completed";

            })
            .slice(0, 5);

        if (upcoming.length === 0) {

            showEmpty(container, "No upcoming tasks.");

            return;
        }

        upcoming.forEach(function (task) {

            const item = document.createElement("div");
            item.className = "wf-event-item";

            const dot = document.createElement("span");
            dot.className = "wf-dot blue";

            const content = document.createElement("div");

            const link = document.createElement("a");

            link.href = task.editUrl;
            link.textContent = task.title;
            link.style.color = "#2563eb";
            link.style.fontSize = "12px";

            const date = document.createElement("small");

            date.textContent = formatDate(task.date);

            content.appendChild(link);
            content.appendChild(date);

            item.appendChild(dot);
            item.appendChild(content);

            container.appendChild(item);
        });
    }

    // 11. Show the selected calendar view.
    function showActiveView() {

        document.querySelectorAll(
            "[data-calendar-view-btn]"
        ).forEach(function (button) {

            button.classList.toggle(
                "active",
                button.dataset.calendarViewBtn === activeView
            );

        });

        document.querySelectorAll(
            "[data-calendar-panel]"
        ).forEach(function (panel) {

            panel.hidden =
                panel.dataset.calendarPanel !== activeView;

        });
    }

    // 12. Refresh all calendar sections.
    function renderAll() {

        renderMonth();
        renderDay();
        renderWeek();
        renderList();
        renderUpcoming();
        showActiveView();
    }

    // 13. Previous and next month.
    document.querySelectorAll(
        "[data-calendar-shift]"
    ).forEach(function (button) {

        button.addEventListener("click", function () {

            const shift = Number(
                button.dataset.calendarShift
            );

            displayedMonth = new Date(
                displayedMonth.getFullYear(),
                displayedMonth.getMonth() + shift,
                1
            );

            selectedDate = dateKey(displayedMonth);

            renderAll();
        });

    });

    // 14. Today button.
    document.querySelector(
        "[data-calendar-today]"
    ).addEventListener("click", function () {

        const current = new Date();

        displayedMonth = new Date(
            current.getFullYear(),
            current.getMonth(),
            1
        );

        selectedDate = dateKey(current);
        activeView = "month";

        renderAll();
    });

    // 15. Month / Week / Day / List buttons.
    document.querySelectorAll(
        "[data-calendar-view-btn]"
    ).forEach(function (button) {

        button.addEventListener("click", function () {

            activeView = button.dataset.calendarViewBtn;

            renderAll();
        });

    });

    // 16. Project and status filters.
    projectFilter.addEventListener(
        "change",
        renderAll
    );

    statusFilter.addEventListener(
        "change",
        renderAll
    );

    // Initial display.
    renderAll();

});
